theorem commutator_inv_left_of_mem {x a : G}
    (ha : a ∈ Subgroup.normalClosure ({x} : Set G)) (g : G) :
    ⁅a⁻¹, g⁆ = ⁅a, g⁆⁻¹

theorem commutator_mem_normalClosure {x a : G}
